var timerRegistry = context.get('timerRegistry') || {};
var scheduleInfo = context.get('scheduleInfo') || {};

var rules = msg.automationRules || global.get('automationRules') || [];
if (typeof rules === 'string') {
    try { rules = JSON.parse(rules); } catch(e) { rules = []; }
}

Object.keys(timerRegistry).forEach(function(key) {
    if (timerRegistry[key]) {
        clearTimeout(timerRegistry[key]);
        delete timerRegistry[key];
    }
});
scheduleInfo = {};

function calculateNextRunTime(timeConds, fromDate) {
    var now = fromDate || new Date();
    var nowDay = now.getDay();
    var nowMinutes = now.getHours() * 60 + now.getMinutes();
    var nowSeconds = now.getSeconds();
    var bestTime = null;
    for (var i = 0; i < timeConds.length; i++) {
        var cond = timeConds[i];
        var days = (cond.days && cond.days.length > 0) ? cond.days.map(Number) : [0,1,2,3,4,5,6];
        var times = [];
        if (cond.timeMode === 'specific') {
            (cond.times || []).forEach(function(t) { var p = t.split(':').map(Number); times.push(p[0]*60+(p[1]||0)); });
        } else if (cond.timeMode === 'interval') {
            var sp = (cond.startTime||'00:00').split(':').map(Number);
            var ep = (cond.endTime||'23:59').split(':').map(Number);
            var start = sp[0]*60+sp[1], end = ep[0]*60+ep[1];
            var interval = cond.intervalMinutes || 30;
            for (var t = start; t <= end; t += interval) times.push(t);
        } else if (cond.time) {
            var p = cond.time.split(':').map(Number); times.push(p[0]*60+(p[1]||0));
        }
        if (times.length === 0) continue;
        times.sort(function(a,b){return a-b;});
        for (var dayOffset = 0; dayOffset < 7; dayOffset++) {
            var checkDay = (nowDay + dayOffset) % 7;
            if (days.indexOf(checkDay) === -1) continue;
            for (var j = 0; j < times.length; j++) {
                var targetMin = times[j];
                if (dayOffset === 0 && (targetMin < nowMinutes || (targetMin === nowMinutes && nowSeconds > 0))) continue;
                var targetDate = new Date(now);
                targetDate.setDate(targetDate.getDate() + dayOffset);
                targetDate.setHours(Math.floor(targetMin/60), targetMin%60, 0, 0);
                if (!bestTime || targetDate < bestTime) bestTime = targetDate;
                break;
            }
            if (bestTime) break;
        }
    }
    return bestTime;
}

var scheduledCount = 0;

rules.forEach(function(rule) {
    if (!rule.enabled) return;
    var timeConds = (rule.conditions || []).filter(function(c) { return c.type === 'time'; });
    if (timeConds.length === 0) return;
    var ruleId = rule._id || rule.id;
    var fromDate = new Date();
    if (rule.lastTriggeredAt) {
        var cooldownEnd = new Date(new Date(rule.lastTriggeredAt).getTime() + (rule.cooldownSeconds || 300) * 1000);
        if (cooldownEnd > fromDate) fromDate = cooldownEnd;
    }
    var nextRun = calculateNextRunTime(timeConds, fromDate);
    if (!nextRun) return;
    var delay = nextRun.getTime() - Date.now();
    if (delay < 0) delay = 0;
    if (delay > 24*60*60*1000) return;
    scheduleInfo[ruleId] = { ruleName: rule.name, nextRunAt: nextRun.toISOString(), delayMs: delay };

    timerRegistry[ruleId] = setTimeout(function scheduleExec() {
        var currentAutoDevices = global.get('autoDevices') || [];
        var actions = (typeof rule.actions === 'string') ? JSON.parse(rule.actions) : (rule.actions || []);
        var executableActions = [];
        actions.forEach(function(action) {
            if (currentAutoDevices.indexOf(action.deviceId) === -1) {
                node.warn('⛔ 스케줄러: ' + action.deviceId + ' 수동 모드 스킵');
                return;
            }
            executableActions.push(action);
        });
        if (executableActions.length === 0) {
            node.warn('⏭️ 스케줄러: ' + rule.name + ' — 실행 가능 액션 없음');
        } else {
            node.warn('🎯 스케줄러 실행: ' + rule.name + ' (' + new Date().toLocaleTimeString() + ')');
            node.send([{ scheduledRule: rule, scheduledActions: executableActions, scheduledAt: new Date().toISOString(), topic: 'scheduled_execution' }, null]);
        }
        delete timerRegistry[ruleId];
        var nextFrom = new Date(Date.now() + (rule.cooldownSeconds || 300) * 1000);
        var nextNext = calculateNextRunTime(timeConds, nextFrom);
        if (nextNext) {
            var nextDelay = nextNext.getTime() - Date.now();
            if (nextDelay > 0 && nextDelay <= 24*60*60*1000) {
                scheduleInfo[ruleId] = { ruleName: rule.name, nextRunAt: nextNext.toISOString(), delayMs: nextDelay };
                timerRegistry[ruleId] = setTimeout(scheduleExec, nextDelay);
                context.set('timerRegistry', timerRegistry);
                context.set('scheduleInfo', scheduleInfo);
                global.set('automationSchedule', scheduleInfo);
            }
        }
    }, delay);
    scheduledCount++;
});

context.set('timerRegistry', timerRegistry);
context.set('scheduleInfo', scheduleInfo);
global.set('automationSchedule', scheduleInfo);
node.warn('📅 스케줄러: ' + scheduledCount + '개 규칙 예약 완료');

var debugInfo = Object.keys(scheduleInfo).map(function(id) {
    var s = scheduleInfo[id];
    return s.ruleName + ' → ' + s.nextRunAt + ' (' + Math.round(s.delayMs/1000) + '초 후)';
}).join('\n');
node.send([null, { payload: debugInfo || '예약된 규칙 없음', topic: 'schedule_info' }]);

