var rule = msg.scheduledRule;
var actions = msg.scheduledActions;
if (!rule || !actions || actions.length === 0) {
    node.warn('⚠️ 스케줄 실행: 규칙/액션 없음');
    return null;
}
var ruleId = rule._id || rule.id;
var REVERSE_CMD = { on:'off', off:'on', open:'close', close:'open' };

function findModbus(deviceId) {
    var cached = global.get('modbus_cfg_' + deviceId);
    if (cached) return cached;
    var houseConfigs = global.get('houseConfigs') || {};
    var keys = Object.keys(houseConfigs);
    for (var i = 0; i < keys.length; i++) {
        var devices = (houseConfigs[keys[i]] || {}).devices || [];
        for (var j = 0; j < devices.length; j++) {
            if (devices[j].deviceId === deviceId && devices[j].modbus) {
                global.set('modbus_cfg_' + deviceId, devices[j].modbus);
                return devices[j].modbus;
            }
        }
    }
    return null;
}

var controlMsgs = [];
var logParts = [];

actions.forEach(function(action) {
    var modbus = findModbus(action.deviceId);
    if (!modbus) { node.warn('⚠️ ' + action.deviceId + ': Modbus 설정 없음'); return; }
    var controlMsg = RED.util.cloneMessage(msg);
    controlMsg.payload = { deviceId: action.deviceId, command: action.command, modbus: modbus, source: 'automation_scheduler' };
    controlMsgs.push(controlMsg);
    logParts.push(action.deviceId + ' ' + action.command);

    var duration = action.duration || 0;
    if (action.durationUnit === 'minutes') duration = duration * 60;
    else if (action.durationUnit === 'hours') duration = duration * 3600;
    if (duration > 0 && REVERSE_CMD[action.command]) {
        var reverseCmd = REVERSE_CMD[action.command];
        node.warn('⏱️ Duration: ' + action.deviceId + ' ' + duration + '초 후 → ' + reverseCmd);
        (function(devId, revCmd, mod, dur) {
            setTimeout(function() {
                var reverseMsg = RED.util.cloneMessage(msg);
                reverseMsg.payload = { deviceId: devId, command: revCmd, modbus: mod, source: 'automation_duration' };
                node.warn('⏳ Duration 종료: ' + devId + ' → ' + revCmd);
                node.send([reverseMsg, null, null]);
            }, dur * 1000);
        })(action.deviceId, reverseCmd, modbus, duration);
    }
});

var now = new Date().toISOString();
var dbMsg = {
    topic: "UPDATE automation_rules SET last_triggered_at = '" + now + "', trigger_count = " + ((rule.triggerCount || 0) + 1) + " WHERE id = '" + ruleId + "'",
    payload: []
};

node.warn('🎯 스케줄 실행: ' + rule.name + ' → ' + logParts.join(', '));

if (controlMsgs.length > 0) {
    var firstMsg = controlMsgs[0];
    for (var k = 1; k < controlMsgs.length; k++) {
        (function(m, d) { setTimeout(function() { node.send([m, null, null]); }, d); })(controlMsgs[k], k * 200);
    }
    return [firstMsg, dbMsg, { payload: '스케줄 실행: ' + rule.name }];
}
return [null, dbMsg, { payload: '스케줄 실행(제어없음): ' + rule.name }];
